insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-eq-126', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'For $\mathrm{A}(g) + \mathrm{B}(g) \rightleftharpoons \mathrm{C}(g)$, equilibrium concentrations are $[\mathrm{A}] = 1$, $[\mathrm{B}] = 1$, $[\mathrm{C}] = 2$ (all in mol L^{-1}). $K_c$ is', '["$2$","$0.5$","$1$","$4$"]'::jsonb, 0, '$K_c = [C]/([A][B]) = 2/(1 \times 1) = 2$ (units L mol^{-1}).', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'kc-kp') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
