insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-eq-128', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'The equilibrium $2\mathrm{HI} \rightleftharpoons \mathrm{H_2} + \mathrm{I_2}$ has $K_c = 0.25$. Starting with $1.0$ mol HI in a $1.0$ L bulb, the equilibrium amount of H2 is', '["$0.25\\ \\mathrm{mol}$","$0.50\\ \\mathrm{mol}$","$0.125\\ \\mathrm{mol}$","$1.0\\ \\mathrm{mol}$"]'::jsonb, 0, 'If $x$ mol of H2 form, $K_c = x^2/(1-2x)^2 = 0.25$, so $x/(1-2x) = 1/2$, hence $x = 0.25$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'kc-kp') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
