insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-eq-129', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'If $K_1$ is the constant for $\mathrm{A} \rightleftharpoons \mathrm{B}$ and $K_2$ for $\mathrm{B} \rightleftharpoons \mathrm{C}$, the constant for $\mathrm{A} \rightleftharpoons \mathrm{C}$ is', '["$K_1 K_2$","$K_1 + K_2$","$K_1/K_2$","$K_2/K_1$"]'::jsonb, 0, 'The overall quotient is the product of the stepwise quotients, so overall $K = K_1 K_2$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'kc-kp') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
