insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-eq-133', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'For $\mathrm{PCl_5}(g) \rightleftharpoons \mathrm{PCl_3}(g) + \mathrm{Cl_2}(g)$ at $300\ \mathrm{K}$, $K_p = 24.6\ \mathrm{atm}$. With $R = 0.082\ \mathrm{L\ atm\ K^{-1}\ mol^{-1}}$, $K_c$ in mol L^{-1} is', '["$1.0$","$24.6$","$0.082$","$300$"]'::jsonb, 0, '$\Delta n = +1$, so $K_c = K_p/(RT) = 24.6/(0.082 \times 300) = 24.6/24.6 = 1.0$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'kc-kp') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
